local function _V(...)
    local _P = 1
    local _S = {}
    local _E = getfenv() or _G
    
    -- 定数テーブルをその場で復号する
    local _DC = {}
    for i, v in ipairs(_C) do
        local s = ""
        for j = 1, #v do 
